<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-3"><div class="w-full max-w-2xl max-h-[88vh] overflow-hidden border border-slate-200 bg-white shadow-lg"><div class="flex items-center justify-between border-b border-slate-200 px-4 py-2.5"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Offplan financing</p><h2 class="text-sm font-semibold text-slate-900">New bank financing</h2></div><button @click="close" class="h-7 w-7 border border-slate-300 text-sm">×</button></div><form @submit.prevent="submit"><div class="grid max-h-[calc(88vh-112px)] gap-2 overflow-y-auto p-3 md:grid-cols-2"><Field v-for="f in textFields" :key="f" :label="label(f)"><input v-model="form[f]" class="input"/></Field><Field label="Loan term months"><input v-model.number="form.loan_term_months" type="number" min="1" class="input"/></Field><Field label="Loan status"><select v-model="form.loan_status" class="input"><option v-for="s in loanStatuses" :key="s" :value="s">{{s}}</option></select></Field><Field label="Approved at"><input v-model="form.approved_at" type="datetime-local" class="input"/></Field><Field label="First payment date"><input v-model="form.first_payment_date" type="date" class="input"/></Field><Field label="Application"><select v-model="form.application" class="input"><option value="0">Select application</option><option v-for="a in applications" :key="a.id" :value="a.id">{{applicationLabel(a)}}</option></select></Field></div><div v-if="error" class="mx-3 mb-2 flex h-7 items-center overflow-hidden border border-red-200 bg-red-50 px-2 text-[10px] text-red-700" :title="error">{{error}}</div><div class="flex justify-end gap-2 border-t border-slate-200 px-3 py-2"><button type="button" @click="close" class="border border-slate-300 px-3 py-1.5 text-xs">Cancel</button><button :disabled="loading" class="bg-primary px-3 py-1.5 text-xs font-semibold text-white">{{loading?'Saving…':'Create financing'}}</button></div></form></div></div></template>
<script>
import OffplanField from "../offplan property/OffplanField.vue";
const blank=()=>({bank_name:"",loan_account_number:"",loan_amount:"",interest_rate:"",loan_term_months:0,monthly_payment:"",loan_status:"pending",approved_at:"",first_payment_date:"",notes:"",application:0});
export default{name:"AddOffplanBankFinancing",components:{Field:OffplanField},props:{open:Boolean},data(){return{form:blank(),applications:[],loading:false,error:"",textFields:["bank_name","loan_account_number","loan_amount","interest_rate","monthly_payment","notes"],loanStatuses:["pending","approved","rejected","active","completed","cancelled"]}},watch:{open(v){if(v){this.form=blank();this.error="";this.loadApplications()}},methods:{label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},applicationLabel(a){return a.name||a.title||a.application_number||a.reference||a.code||a.customer_name||a.client_name||("Application #"+a.id)},async loadApplications(){try{const r=await this.$apiGet("/get_offplan_applications");const d=r?.data?.data||r?.data||r?.applications||r;this.applications=Array.isArray(d)?d:(d?.results||d?.applications||[])}catch(e){this.error=e?.message||"Unable to load applications."}},close(){if(!this.loading)this.$emit("close")},async submit(){this.loading=true;this.error="";try{await this.$apiPost("/post_offplan_bank_financing",{...this.form,loan_term_months:Number(this.form.loan_term_months),application:Number(this.form.application)});this.$emit("saved");this.close()}catch(e){this.error=e?.message||"Unable to create financing."}finally{this.loading=false}}}};
</script>
<style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.4rem .55rem;font-size:.75rem;line-height:1rem;outline:none;background:#fff}.input:focus{border-color:#5f5ffc}</style>